CREATE PERFETTO TABLE phases AS SELECT name,ts,dur FROM slice WHERE name GLOB 'open|[23]|*' OR name GLOB 'return|[23]|*';
SELECT p.name,t.name,count(*) frames,round(percentile(s.dur,95)/1e6,2) p95_ms,round(max(s.dur)/1e6,2) max_ms FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.name IN('com.android.launcher','com.android.systemui') AND s.name LIKE 'Choreographer#doFrame %' AND s.dur>0 AND EXISTS(SELECT 1 FROM phases q WHERE s.ts>=q.ts AND s.ts<q.ts+q.dur) GROUP BY t.utid;
CREATE PERFETTO TABLE comp AS SELECT s.ts,lag(s.ts) OVER (ORDER BY s.ts) prev FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.name='/system/bin/surfaceflinger' AND t.tid=p.pid AND s.name GLOB 'composite [0-9]*';
SELECT count(*) intervals,round(percentile(c.ts-c.prev,95)/1e6,2) cadence95_ms,round(max(c.ts-c.prev)/1e6,2) cadence_max_ms,sum(c.ts-c.prev>25000000) intervals_gt25ms FROM comp c WHERE EXISTS(SELECT 1 FROM phases q WHERE q.name GLOB 'return|*' AND c.prev>=q.ts AND c.ts<q.ts+q.dur);
SELECT count(*) attempts,sum(exists(SELECT 1 FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.name='com.android.launcher' AND s.name LIKE 'dispatchInputEvent MotionEvent ACTION_UP%' AND s.ts>=q.ts AND s.ts<q.ts+q.dur)) delivered_to_launcher FROM phases q WHERE q.name GLOB 'open|*';
SELECT p.name,t.name,round(sum(sc.dur)/1e6,1) cpu_ms,round(sum(case when sc.cpu<4 then sc.dur else 0 end)*100.0/sum(sc.dur),1) little_core_percent FROM sched sc JOIN thread t USING(utid) JOIN process p USING(upid) WHERE sc.dur>0 AND p.name IN('com.android.launcher','com.android.systemui') AND (t.tid=p.pid OR t.name IN('RenderThread','wmshell.main','launcher.anim','GestureUI')) GROUP BY t.utid ORDER BY p.name,t.name;
SELECT count(*) creation_count,round(max(dur)/1e6,2) max_creation_ms FROM slice WHERE name LIKE 'VRI[StatusBar InputLayer%relayoutWindow#first=true%';
SELECT name,value FROM stats WHERE value>0 AND (severity='data_loss' OR severity='error');
